//! Java mods' world presets on the dedicated server (`level-type`).
use horizon_world::nbt::Tag;

/// A mod's world preset (level-type=oneblock:oneblock), generated by the Java mods: its
/// dimensions, from the mods' data in `resources`, and its id. None for vanilla's.
pub(super) fn mod_preset(
    resources: &std::path::Path,
    id: Option<&str>,
) -> (Option<Tag>, Option<String>) {
    let dimensions = id
        .filter(|id| !id.starts_with("minecraft:"))
        .and_then(|id| horizon_client::save::preset_dimensions(resources, id));
    let mod_preset = dimensions.as_ref().and(id.map(str::to_owned));
    (dimensions, mod_preset)
}
